Este provider usa un único RAF —el ticker de GSAP—, actualiza `ScrollTrigger` con cada evento de Lenis y desactiva `lagSmoothing`. Es la integración recomendada oficialmente por [Lenis](https://github.com/darkroomengineering/lenis#gsap-scrolltrigger) y [GSAP](https://gsap.com/docs/v3/GSAP/gsap.ticker/).

```tsx
// components/providers/lenis-provider.tsx
"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type PropsWithChildren,
} from "react";
import Lenis from "lenis";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const LenisContext = createContext<Lenis | null>(null);

export function useLenis() {
  return useContext(LenisContext);
}

export function LenisProvider({ children }: PropsWithChildren) {
  const [lenis, setLenis] = useState<Lenis | null>(null);

  useEffect(() => {
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    );

    const previousScrollRestoration =
      window.history.scrollRestoration;

    let instance: Lenis | null = null;
    let refreshFrame: number | null = null;

    const updateScrollTrigger = () => {
      ScrollTrigger.update();
    };

    const tick = (time: number) => {
      instance?.raf(time * 1000);
    };

    const stop = () => {
      if (refreshFrame !== null) {
        cancelAnimationFrame(refreshFrame);
        refreshFrame = null;
      }

      if (!instance) return;

      instance.off("scroll", updateScrollTrigger);
      gsap.ticker.remove(tick);
      instance.destroy();
      instance = null;

      window.history.scrollRestoration =
        previousScrollRestoration;
    };

    const start = () => {
      if (reducedMotion.matches) {
        setLenis(null);
        return;
      }

      window.history.scrollRestoration = "manual";

      instance = new Lenis({
        autoRaf: false,
      });

      instance.on("scroll", updateScrollTrigger);
      gsap.ticker.add(tick);

      // Evita saltos al volver desde una pestaña en segundo plano.
      gsap.ticker.lagSmoothing(0);

      setLenis(instance);

      // Recalcula posiciones después de montar el layout.
      refreshFrame = requestAnimationFrame(() => {
        ScrollTrigger.refresh();
        refreshFrame = null;
      });
    };

    const handleMotionPreference = () => {
      stop();
      setLenis(null);
      start();
    };

    start();
    reducedMotion.addEventListener(
      "change",
      handleMotionPreference,
    );

    return () => {
      reducedMotion.removeEventListener(
        "change",
        handleMotionPreference,
      );
      stop();
    };
  }, []);

  return (
    <LenisContext.Provider value={lenis}>
      {children}
    </LenisContext.Provider>
  );
}
```

Móntalo una sola vez en el layout raíz:

```tsx
import "lenis/dist/lenis.css";
import { LenisProvider } from "@/components/providers/lenis-provider";

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="es">
      <body>
        <LenisProvider>{children}</LenisProvider>
      </body>
    </html>
  );
}
```

No necesita `ScrollTrigger.scrollerProxy()`: Lenis conserva el scroll nativo y aquí ambos sistemas quedan sincronizados mediante el ticker. Desde un componente hijo puedes obtener la instancia con `useLenis()?.scrollTo(...)`.
